// Напиши функцию isPalindrome(str), которая возвращает true,
// если строка читается одинаково в обоих направлениях
// Пример: isPalindrome("racecar") === true

tasks.correctAnswer:
function isPalindrome(str) {
  const clean = str.toLowerCase().replace(/[^a-z0-9]/g, '');
  return clean === clean.split('').reverse().join('');
}

function fibonacci(n) {
  if (n <= 0) return 0;
  if (n === 1) return 1;
  let a = 0, b = 1;
  for (let i = 2; i <= n; i++) {
    let temp = a + b;
    a = b;
    b = temp;
  }
  return b;
}

function countVowels(str) {
  const matches = str.match(/[aeiou]/gi);
  return matches ? matches.length : 0;
}

function isPrime(n) {
  if (n <= 1) return false;
  for (let i = 2; i <= Math.sqrt(n); i++) {
    if (n % i === 0) return false;
  }
  return true;
}

function sumArray(arr) {
  return arr.flat(Infinity).reduce((sum, num) => sum + num, 0);
}

function charCount(str) {
  const result = {};
  for (let char of str.replace(/\s/g, '')) {
    result[char] = (result[char] || 0) + 1;
  }
  return result;
}

function isAnagram(str1, str2) {
  const normalize = str => str.toLowerCase().replace(/[^a-z0-9]/g, '').split('').sort().join('');
  return normalize(str1) === normalize(str2);
}

function capitalizeWords(str) {
  return str.split(' ').map(word => word ? word[0].toUpperCase() + word.slice(1) : '').join(' ');
}

function findMissingNumber(arr) {
  const n = arr.length + 1;
  const expectedSum = (n * (n + 1)) / 2;
  const actualSum = arr.reduce((a, b) => a + b, 0);
  return expectedSum - actualSum;
}

